OVERRIDES={
 'src/bin/jobctl.rs':{'git_blob_sha1':'cd5989b57e2249d9c7e78a76ceb29db5f1d5dbf7','sha256':'c22fdcd5bafad3a2123d5817c27fd73e7b5c26001bf1a8bdd6f8dbacabc8b562'},
 'src/mcp/runtime/jobs.rs':{'git_blob_sha1':'758bdda38b58f01d1cd281661a165d5f033779bd','sha256':'f7c23620d2d79c5a02938b432e90f8dadb6352a897bf5a575547eabc121119f4'},
}

def need(value,message):
    if not value: raise ValueError(message)

def stamp(s):
    return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)

def enumerate_inputs():
    need(SOURCE.is_dir() and not SOURCE.is_symlink(),'source root is not a plain directory')
    paths=[]
    for name in ('Cargo.toml','Cargo.lock','rustfmt.toml'):
        s=(SOURCE/name).lstat()
        need(stat.S_ISREG(s.st_mode) and s.st_nlink==1,'root input is not an independent regular file: '+name)
        paths.append(name)
    def walk(directory,relative):
        s=directory.lstat()
        need(stat.S_ISDIR(s.st_mode),'input directory is not a plain directory: '+relative)
        with os.scandir(directory) as entries:
            for entry in sorted(entries,key=lambda x:x.name):
                child=relative+'/'+entry.name
                s=entry.stat(follow_symlinks=False)
                if stat.S_ISDIR(s.st_mode):
                    walk(Path(entry.path),child)
                else:
                    need(stat.S_ISREG(s.st_mode) and s.st_nlink==1,'input is linked or special: '+child)
                    paths.append(child)
    for name in ('src','examples'):
        walk(SOURCE/name,name)
    return sorted(paths)

def hash_input(relative):
    path=SOURCE/relative
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    try:
        before=os.fstat(fd)
        need(stat.S_ISREG(before.st_mode) and before.st_nlink==1,'input type changed: '+relative)
        content=hashlib.sha256()
        blob=hashlib.sha1(b'blob '+str(before.st_size).encode()+b'\0')
        count=0
        while True:
            block=os.read(fd,65536)
            if not block: break
            count+=len(block);content.update(block);blob.update(block)
        need(count==before.st_size,'input size changed: '+relative)
        need(stamp(before)==stamp(os.fstat(fd))==stamp(path.stat(follow_symlinks=False)),
             'input identity changed during read: '+relative)
        return {'path':relative,'bytes':count,'sha256':content.hexdigest(),'git_blob_sha1':blob.hexdigest()}
    finally:
        os.close(fd)

def main():
    raw_report=REPORT.read_bytes()
    report_sha=hashlib.sha256(raw_report).hexdigest()
    need(report_sha==EXPECTED_REPORT_SHA256,'qualified report identity differs')
    report=json.loads(raw_report)
    need(report.get('qualified') is True,'report is not qualified')
    need(report.get('source')==str(SOURCE),'qualification source path differs')
    paths=enumerate_inputs()
    need(len(paths)==219 and len(BASELINE_BLOBS)==219,'expected exactly 219 inputs')
    need(set(paths)==set(BASELINE_BLOBS),'source compile input inventory differs from baseline Git tree')
    maps={key:report[key] for key in ('source_input','source_tested','source_after')}
    need(all(set(value)==set(paths) for value in maps.values()),'qualification input inventory differs')
    need(maps['source_input']==maps['source_tested']==maps['source_after'],'qualification source maps disagree')
    files=[hash_input(path) for path in paths]
    by_path={row['path']:row for row in files}
    expected_git=dict(BASELINE_BLOBS)
    expected_git.update({path:value['git_blob_sha1'] for path,value in OVERRIDES.items()})
    mismatches=[{'path':path,'actual_git':by_path[path]['git_blob_sha1'],'expected_git':expected_git[path]}
                for path in paths if by_path[path]['git_blob_sha1']!=expected_git[path]]
    qualified_mismatches=[path for path in paths if by_path[path]['sha256']!=maps['source_after'][path]]
    changed=[path for path in paths if by_path[path]['git_blob_sha1']!=BASELINE_BLOBS[path]]
    checks={
      'qualified_report_sha256_matches':report_sha==EXPECTED_REPORT_SHA256,
      'qualified':report.get('qualified') is True,
      '219_compile_inputs':len(files)==219,
      'no_added_or_deleted_compile_inputs':set(paths)==set(BASELINE_BLOBS),
      'qualification_input_sets_equal':all(set(value)==set(paths) for value in maps.values()),
      'qualification_source_maps_equal':maps['source_input']==maps['source_tested']==maps['source_after'],
      'all_current_sha256_match_qualification':not qualified_mismatches,
      'all_git_blobs_match_baseline_plus_two_overrides':not mismatches,
      'only_two_git_blob_changes':changed==sorted(OVERRIDES),
      'override_sha256_matches':all(by_path[path]['sha256']==value['sha256'] for path,value in OVERRIDES.items()),
      'cargo_lock_rustfmt_unchanged':all(by_path[name]['git_blob_sha1']==BASELINE_BLOBS[name] for name in ('Cargo.toml','Cargo.lock','rustfmt.toml')),
      'input_inventory_unchanged_after_reads':enumerate_inputs()==paths,
      'qualified_report_unchanged_after_reads':hashlib.sha256(REPORT.read_bytes()).hexdigest()==report_sha,
    }
    result={'schema':'hepta-r17-qualified-source-git-observation/v1','success':all(checks.values()),
      'source':str(SOURCE),'report_path':str(REPORT),'report_sha256':report_sha,
      'baseline_commit':BASELINE_COMMIT,'baseline_root_tree':BASELINE_ROOT_TREE,
      'checks':checks,'file_count':len(files),'changed_paths':changed,'files':files,
      'git_mismatches':mismatches,'qualification_sha256_mismatches':qualified_mismatches,
      'comparison_scope':'Every compile input is independently opened and hashed; per-file descriptor/path stamps and before/after inventory are checked.',
      'source_writes':False,'compilation_or_tests_run':False}
    print(json.dumps(result,sort_keys=True,separators=(',',':')))
    return 0 if result['success'] else 1

if __name__=='__main__':
    raise SystemExit(main())
